"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[58130],{91015(e,t,n){n.r(t),n.d(t,{assets:()=>d,contentTitle:()=>a,default:()=>c,frontMatter:()=>r,metadata:()=>o,toc:()=>h});const o=JSON.parse('{"id":"general/onboarding-our-first-it-employee","title":"Onboarding Our First It Employee","description":"By steven","source":"@site/docs/general/onboarding-our-first-it-employee.md","sourceDirName":"general","slug":"/general/onboarding-our-first-it-employee","permalink":"/jc-community-archive/general/onboarding-our-first-it-employee","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Onboarding Our First It Employee","description":"By steven"},"sidebar":"docs","previous":{"title":"Onboarder Exe To Assign Users By Using A Command After Agent","permalink":"/jc-community-archive/general/onboarder-exe-to-assign-users-by-using-a-command-after-agent"},"next":{"title":"Onboarding Script Report For Each System The Users It Has And If","permalink":"/jc-community-archive/general/onboarding-script-report-for-each-system-the-users-it-has-and-if"}}');var s=n(74848),i=n(28453);const r={title:"Onboarding Our First It Employee",description:"By steven"},a=void 0,d={},h=[];function l(e){const t={a:"a",em:"em",li:"li",p:"p",ul:"ul",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.p,{children:"My company has officially on boarded our first IT person! But Steven, you may be asking, you're the Systems Administrator, weren\u2019t you the first IT person? Yes and no. When I was hired, I applied for a Drupal developer position with a little bit of sysadmin work. In a shock to no one in the IT community, the sysadmin work was much larger than expected, and I slowly transitioned over to full-time sysadmin. Since I wasn\u2019t hired with the sole intention of being the systems administrator, I don\u2019t really count myself as our first IT person."}),"\n",(0,s.jsx)(t.p,{children:"Back to the main point of this post. Once we decided we were going to hire a Junior Systems Administrator, our COO, VP of Strategy, and myself sat down and figured out what on boarding was going to look like. We landed on the following items:"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"Create accounts for him as if he was a developer."}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"Password management account, Git account, Developer VPN access, SSH access to servers, etc."}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"Development access worked well, because it has the most access to our infrastructure without giving admin privileges."}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"Leave that as is for the first 30 days. If things were going well, after 30 days start giving him some admin privileges as needed."}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"We didn\u2019t want to give admin privileges to everything immediately for obvious security reasons (and we didn\u2019t want him accidentally deleting our entire JumpCloud organization)."}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"After 60 days have him start doing on boarding of new employees as needed - We just happened to have a new employee get hired shortly after his 60 days so it worked out perfectly."}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"I sat down with him and walked him through the on boarding process, ensuring he had admin privileges to what was needed."}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"After 90 days, we\u2019d introduce him to our vendor contacts. We decided on 90 days because this is the end of our typical \u201con boarding\u201d process for most employees. And at this point we would have a firm idea on if he was going to be a good long term fit on the team."}),"\n"]}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:["We were all pretty happy with this plan, as it allowed us and the organization as a whole to ensure he wasn\u2019t going to nuke our entire infrastructure (he could be playing the long-con, that\u2019s still to be determined. I\u2019ll write a follow up if he is.). I also wanted to make sure he didn\u2019t feel like we didn\u2019t trust him and never would, and that he didn\u2019t get frustrated because he didn\u2019t feel like he could do the job effectively. Occasionally you\u2019ll hear about new IT hires who are frustrated because they have access to nothing and their managers don\u2019t trust them. In the SysAdmin subreddit the general consensus among managers and Sr. staff is \u201cWell we don\u2019t trust you. Get over it.\u201d While that is true to some extent, I wanted to make sure that he knew that \u201cSure, we don\u2019t trust you with the keys to the kingdom right now, but we ",(0,s.jsx)(t.em,{children:"will"})," trust you as time goes on\u201d.\xa0"]}),"\n",(0,s.jsx)(t.p,{children:"Here\u2019s where I get a bit technical, so if you\u2019re only here for the rough \u201chere\u2019s how we on boarded our first IT person\u201d then you probably want to skip to the end where I introduce you to our new Junior Systems Administrator. If you\u2019re a tech nerd like me, read on!"}),"\n",(0,s.jsxs)(t.p,{children:["The first admin privileges that our new Jr. SysAdmin needed access to was JumpCloud\u2019s admin portal. After reading through the ",(0,s.jsx)(t.a,{href:"https://support.jumpcloud.com/s/article/JumpCloud-Roles",children:"JumpCloud Admin Roles support page"})," (which I wish would get updated to remove the legacy roles that don\u2019t exist anymore @Anonymous\xa0), I decided upon \u201cManager.\u201d It gave him access to modify users in the case we needed a password reset, enroll and modify devices, and work with commands. The one hesitation I had with this role was that it also allowed him to delete users, but I had hoped (and not verified, I know\u2026 shame on me) that JumpCloud could undo it if he accidentally deleted a user.\xa0"]}),"\n",(0,s.jsx)(t.p,{children:"The next set was giving him sudo privileges to servers. There were a few that I kept restricted, like our internal app that stores a lot of the company data\u2014I wrote a blog about it here actually\u2014and our network controller server. After that, it was access to our cloud hosting account so that he could create and destroy servers as needed.\xa0"}),"\n",(0,s.jsx)(t.p,{children:"Around this time we hit his 60-day mark, and the time came to give him admin privileges to other software that was required for him to onboard new employees. I walked him through on boarding one employee, and he\u2019s now done one or two others without any issue. Also around this time I bumped up his privileges in JumpCloud, so he\u2019s now an Administrator."}),"\n",(0,s.jsx)(t.p,{children:"And that brings us to the present day. We hit his 90 day review next week and I\u2019ll send out emails to introduce him to all of our vendors. After that, the last step is to get him access to one of our biggest clients' infrastructure. We don\u2019t have a timeline on that, but I expect we\u2019ll start the process here shortly."}),"\n",(0,s.jsx)(t.p,{children:"So you\u2019ve now read nearly 900 words talking about this mystical being, I guess I should actually introduce him."}),"\n",(0,s.jsx)(t.p,{children:"Zach is our Junior Systems Administrator; he\u2019s a fresh college grad and has been fantastic to work with. He\u2019s always willing to take on whatever we throw at him, and while he doesn\u2019t have a development background, he\u2019s been teaching himself some PHP in his downtime (we\u2019re a full PHP shop). For me, he\u2019s been a breath of fresh air. I\u2019ve been single handedly rebuilding, maintaining, expanding, and monitoring our infrastructure for almost 4 years. Having someone dedicated to taking care of some of that has been amazing. I\u2019m beyond excited to see where he goes and the type of stuff we can get done."})]})}function c(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},28453(e,t,n){n.d(t,{R:()=>r,x:()=>a});var o=n(96540);const s={},i=o.createContext(s);function r(e){const t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);